{"file_path":"$BENCH_V3/case-a-plain/backend/src/db.js","content":"const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

function createDb(dbPath) {
  const resolved = dbPath || path.join(__dirname, '..', 'data', 'todos.db');
  const dir = path.dirname(resolved);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const db = new Database(resolved);
  db.pragma('journal_mode = WAL');
  db.exec(`
    CREATE TABLE IF NOT EXISTS todos (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      completed INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `);
  return db;
}

function todoRepo(db) {
  return {
    list() {
      return db
        .prepare('SELECT id, title, completed, created_at AS createdAt FROM todos ORDER BY id DESC')
        .all()
        .map((row) => ({ ...row, completed: !!row.completed }));
    },

    get(id) {
      const row = db
        .prepare('SELECT id, title, completed, created_at AS createdAt FROM todos WHERE id = ?')
        .get(id);
      if (!row) return null;
      return { ...row, completed: !!row.completed };
    },

    create(title) {
      const info = db.prepare('INSERT INTO todos (title) VALUES (?)').run(title);
      return this.get(info.lastInsertRowid);
    },

    update(id, { title, completed }) {
      const existing = this.get(id);
      if (!existing) return null;
      const nextTitle = title !== undefined ? title : existing.title;
      const nextCompleted =
        completed !== undefined ? (completed ? 1 : 0) : existing.completed ? 1 : 0;
      db.prepare('UPDATE todos SET title = ?, completed = ? WHERE id = ?').run(
        nextTitle,
        nextCompleted,
        id
      );
      return this.get(id);
    },

    toggle(id) {
      const existing = this.get(id);
      if (!existing) return null;
      return this.update(id, { completed: !existing.completed });
    },

    remove(id) {
      const info = db.prepare('DELETE FROM todos WHERE id = ?').run(id);
      return info.changes > 0;
    },
  };
}

module.exports = { createDb, todoRepo };
"}

{"file_path":"$BENCH_V3/case-a-plain/backend/src/app.js","content":"const express = require('express');
const cors = require('cors');
const { createDb, todoRepo } = require('./db');

function createApp(options = {}) {
  const db = createDb(options.dbPath);
  const todos = todoRepo(db);
  const app = express();

  app.use(cors());
  app.use(express.json());

  app.get('/api/health', (_req, res) => {
    res.json({ ok: true });
  });

  app.get('/api/todos', (_req, res) => {
    res.json(todos.list());
  });

  app.get('/api/todos/:id', (req, res) => {
    const todo = todos.get(Number(req.params.id));
    if (!todo) return res.status(404).json({ error: 'Todo not found' });
    res.json(todo);
  });

  app.post('/api/todos', (req, res) => {
    const title = typeof req.body?.title === 'string' ? req.body.title.trim() : '';
    if (!title) {
      return res.status(400).json({ error: 'title is required' });
    }
    const todo = todos.create(title);
    res.status(201).json(todo);
  });

  app.put('/api/todos/:id', (req, res) => {
    const id = Number(req.params.id);
    const patch = {};
    if (req.body?.title !== undefined) {
      if (typeof req.body.title !== 'string' || !req.body.title.trim()) {
        return res.status(400).json({ error: 'title must be a non-empty string' });
      }
      patch.title = req.body.title.trim();
    }
    if (req.body?.completed !== undefined) {
      patch.completed = Boolean(req.body.completed);
    }
    const todo = todos.update(id, patch);
    if (!todo) return res.status(404).json({ error: 'Todo not found' });
    res.json(todo);
  });

  app.patch('/api/todos/:id/toggle', (req, res) => {
    const todo = todos.toggle(Number(req.params.id));
    if (!todo) return res.status(404).json({ error: 'Todo not found' });
    res.json(todo);
  });

  app.delete('/api/todos/:id', (req, res) => {
    const ok = todos.remove(Number(req.params.id));
    if (!ok) return res.status(404).json({ error: 'Todo not found' });
    res.status(204).send();
  });

  app.locals.db = db;
  return app;
}

module.exports = { createApp };
"}

