{"file_path":"$BENCH_V3/case-a-plain/frontend/src/App.jsx","content":"import { useCallback, useEffect, useState } from 'react'
import {
  createTodo,
  deleteTodo,
  fetchTodos,
  toggleTodo,
  updateTodo,
} from './api'
import './App.css'

function App() {
  const [todos, setTodos] = useState([])
  const [title, setTitle] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [editingId, setEditingId] = useState(null)
  const [editTitle, setEditTitle] = useState('')

  const load = useCallback(async () => {
    setError('')
    try {
      const data = await fetchTodos()
      setTodos(data)
    } catch (err) {
      setError(err.message || 'Failed to load todos')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    load()
  }, [load])

  async function handleAdd(e) {
    e.preventDefault()
    const trimmed = title.trim()
    if (!trimmed) return
    setError('')
    try {
      const todo = await createTodo(trimmed)
      setTodos((prev) => [todo, ...prev])
      setTitle('')
    } catch (err) {
      setError(err.message || 'Failed to create todo')
    }
  }

  async function handleToggle(id) {
    setError('')
    try {
      const updated = await toggleTodo(id)
      setTodos((prev) => prev.map((t) => (t.id === id ? updated : t)))
    } catch (err) {
      setError(err.message || 'Failed to toggle todo')
    }
  }

  async function handleDelete(id) {
    setError('')
    try {
      await deleteTodo(id)
      setTodos((prev) => prev.filter((t) => t.id !== id))
    } catch (err) {
      setError(err.message || 'Failed to delete todo')
    }
  }

  function startEdit(todo) {
    setEditingId(todo.id)
    setEditTitle(todo.title)
  }

  function cancelEdit() {
    setEditingId(null)
    setEditTitle('')
  }

  async function saveEdit(id) {
    const trimmed = editTitle.trim()
    if (!trimmed) return
    setError('')
    try {
      const updated = await updateTodo(id, { title: trimmed })
      setTodos((prev) => prev.map((t) => (t.id === id ? updated : t)))
      cancelEdit()
    } catch (err) {
      setError(err.message || 'Failed to update todo')
    }
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Todo List</h1>
        <p className="subtitle">Local Express API + React</p>
      </header>

      <form className="add-form" onSubmit={handleAdd}>
        <input
          aria-label="New todo title"
          placeholder="What needs doing?"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      {error ? (
        <p className="error" role="alert">
          {error}
        </p>
      ) : null}

      {loading ? (
        <p className="muted">Loading…</p>
      ) : todos.length === 0 ? (
        <p className="muted">No todos yet. Add one above.</p>
      ) : (
        <ul className="todo-list">
          {todos.map((todo) => (
            <li key={todo.id} className={todo.completed ? 'done' : ''}>
              <input
                type="checkbox"
                checked={todo.completed}
                onChange={() => handleToggle(todo.id)}
                aria-label={`Toggle ${todo.title}`}
              />
              {editingId === todo.id ? (
                <div className="edit-row">
                  <input
                    aria-label="Edit todo title"
                    value={editTitle}
                    onChange={(e) => setEditTitle(e.target.value)}
                  />
                  <button type="button" onClick={() => saveEdit(todo.id)}>
                    Save
                  </button>
                  <button type="button" className="ghost" onClick={cancelEdit}>
                    Cancel
                  </button>
                </div>
              ) : (
                <>
                  <span className="title">{todo.title}</span>
                  <div className="actions">
                    <button type="button" className="ghost" onClick={() => startEdit(todo)}>
                      Edit
                    </button>
                    <button
                      type="button"
                      className="danger"
                      onClick={() => handleDelete(todo.id)}
                    >
                      Delete
                    </button>
                  </div>
                </>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

export default App
"}

